keyConcepts.codeExample:
query = {"réinitialiser", "mot", "passe"}
documents = {
    "compte-utilisateur": {"réinitialiser", "mot", "passe", "compte"},
    "routeur-usine": {"réinitialiser", "routeur", "usine", "mot"},
}
ranked = sorted(documents, key=lambda k: len(query & documents[k]), reverse=True)
print("Classement brut:", ranked)
# Sans pondération métier, un score lexical élevé ne garantit pas la bonne réponse

